#!/usr/bin/env bash
# Creates .env with random secrets on first run. Idempotent: never overwrites.
set -euo pipefail
cd "$(dirname "$0")/.."

if [[ -f .env ]]; then
  echo ".env already exists, leaving it alone."
  exit 0
fi

rand() { openssl rand -base64 36 | tr -d '/+=\n' | cut -c1-40; }

project="${VERTEX_PROJECT_ID:-$(gcloud config get-value project 2>/dev/null || true)}"

cat > .env <<EOF
# Generated by scripts/setup.sh. Never commit this file.

# --- Vertex AI upstream (uses gcloud Application Default Credentials) ---
VERTEX_PROJECT_ID=${project}
VERTEX_REGION=global

# --- Local services ---
POSTGRES_PASSWORD=$(rand)
CLICKHOUSE_PASSWORD=$(rand)
GRAFANA_ADMIN_PASSWORD=$(rand)
OTEL_COLLECTOR_VERSION=latest

# --- Gateway ---
OIDC_CLIENT_SECRET=$(rand)
GATEWAY_JWT_SECRET=$(rand)$(rand)
GATEWAY_ADMIN_WRITE_KEY=$(rand)$(rand)
GATEWAY_ADMIN_READ_KEY=$(rand)$(rand)

# --- Budget app (sign-in password for the admin web app) ---
APP_ADMIN_PASSWORD=$(rand)
EOF
# GATEWAY_POSTGRES_URL is derived at run time from POSTGRES_PASSWORD.
chmod 600 .env
echo "Wrote .env (project=${project:-<unset>}, region=global). Review VERTEX_PROJECT_ID / VERTEX_REGION."
